 for(const r of value.rows){const line=document.createElement('p');line.textContent=labels[r.key]+'：方針＋'+r.focus+'%・継承素質＋'+r.talent+'%'+(r.individual?' ／ 性格・特殊個体による増加＋'+r.individual:'');detail.append(line);}
